import copy,json
from tomlkit import parse,dumps,to_inline_table
cases = {
 "original_mixed": '[parent]\nvalue=1\nparent.child={name="x"}\nparent.dotted=2\n',
 "equivalent_explicit": '[parent]\nvalue=1\n[parent.parent]\nchild={name="x"}\ndotted=2\n',
 "minimal_mixed": '[p]\np.a=1\np.b=2\n',
 "minimal_explicit": '[p.p]\na=1\nb=2\n',
 "control_nested": '[parent]\nvalue=1\n[parent.child]\nname="x"\n',
}
results=[]
for name,text in cases.items():
 doc=parse(text);before=copy.deepcopy(doc.unwrap());key='p' if name.startswith('minimal') else 'parent'
 row={'case':name,'input_data':before,'valid_toml':True,'contains_aot':False}
 try:
  result=to_inline_table(key,doc)
  row.update(completed=True,same_document=result is doc,roundtrip_data_preserved=parse(dumps(doc)).unwrap()==before)
 except Exception as error:
  row.update(completed=False,error_type=type(error).__name__,error=str(error))
 results.append(row)
print(json.dumps(results))
